-- Reemplazo seguro del catálogo de productos.
-- Desactiva productos antiguos, actualiza los 30 SKU del documento y elimina únicamente filas antiguas sin historial relacionado.
begin;
update public.products set active = false where sku not in ('00219','00220','00221','00222','00223','00224','00225','00226','00227','00228','00229','00230','00231','00232','00233','00234','00235','00236','00237','00238','00239','00240','00241','00242','00243','00244','00245','00246','00247','00248');
delete from public.products p where p.active = false and not exists (select 1 from public.answers a where a.product_id = p.id) and not exists (select 1 from public.round_products rp where rp.product_id = p.id);
commit;
